using Godot;
using System;
using System.Collections.Generic;
using System.Globalization;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;

public partial class AudioRendererOperations : RefCounted
{
    private static readonly object PublishGate=new();
    private static Variant Get(Settings source,string key,Variant fallback=default)=>source.TryGetValue(key,out var value)?value:fallback;
    private static bool Bool(Settings source,string key,bool fallback=false)=>source.TryGetValue(key,out var value)?value.AsBool():fallback;
    private static string Text(Settings source,string key,string fallback="")=>source.TryGetValue(key,out var value)?value.AsString():fallback;
    private static double Number(Settings source,string key,double fallback=0)=>source.TryGetValue(key,out var value)?value.AsDouble():fallback;
    private static GArray List(Settings source,string key)=>source.TryGetValue(key,out var value)?value.AsGodotArray():new GArray();
    private static Settings Dict(Settings source,string key)=>source.TryGetValue(key,out var value)?value.AsGodotDictionary():new Settings();
    private static bool Cancelled(RefCounted? job)=>job!=null&&job.Call("is_cancelled").AsBool();
    private static Settings Failure(string message)=>new() {["success"]=false,["error"]=message};
    private static string Format(Variant value)=>AudioEffectsOperations.FormatNumber(value);
    public Settings execute(string encoder,string[] arguments,double duration,RefCounted? job){using var process=new AudioEncoderProcessOperations();return process.run(encoder,arguments,duration,job,0);}
    public Settings encoded_peak(string encoder,string path,double duration,RefCounted? job)
    {
        var result=execute(encoder,new[]{"-nostdin","-hide_banner","-v","info","-threads","1","-i",path,"-af","astats=metadata=0:reset=0","-f","null","-"},duration,job);if(!Bool(result,"success"))return result;double peak=-120;bool found=false;foreach(string line in Text(result,"diagnostics").Split('\n')){int offset=line.IndexOf("Peak level dB:",StringComparison.Ordinal);if(offset<0)continue;string value=line[(offset+14)..].Trim();if(value.ToLowerInvariant().Contains("inf",StringComparison.Ordinal)){if(value.StartsWith('-'))found=true;else return Failure("Non-finite samples in encoded audio.");}else if(double.TryParse(value,NumberStyles.Float,CultureInfo.InvariantCulture,out var number)){found=true;peak=Math.Max(peak,number);}}return found?new Settings {["success"]=true,["peak_db"]=peak,["error"]=""}:Failure("Could not verify the encoded audio peak.");
    }
    public bool route_reaches(RefCounted document,string source,string target,Settings visited)
    {
        var pending=new Stack<string>();pending.Push(source);var seen=new HashSet<string>();foreach(var key in visited.Keys)seen.Add(key.AsString());while(pending.Count>0){string id=pending.Pop();if(id==target)return true;if(!seen.Add(id))continue;var track=document.Call("track_for_id",id).AsGodotDictionary();string output=Text(track,"output");if(output.Length>0)pending.Push(output);foreach(var send in List(track,"sends"))pending.Push(Text(send.AsGodotDictionary(),"target"));}return false;
    }
    public string unsupported_automation(RefCounted document,Settings options)
    {
        var owners=new List<(Settings Owner,string Label,HashSet<string> Allowed)>();if(!Bool(options,"bypass_master_processing"))owners.Add((document.Get("master").AsGodotDictionary(),"Master",new HashSet<string>{"volume_db"}));if(!Bool(options,"bypass_track_processing"))foreach(var raw in document.Get("tracks").AsGodotArray()){var track=raw.AsGodotDictionary();owners.Add((track,Text(track,"name","Track"),new HashSet<string>{"volume_db","pan"}));}var selected=List(options,"clip_ids");var actors=document.Get("actors").AsGodotArray();var clips=document.Get("clips").AsGodotArray();for(int index=0;index<actors.Count;index++){if(selected.Count>0&&!selected.Contains(clips[index].AsGodotObject().Get("id")))continue;var actor=actors[index].AsGodotObject();owners.Add((actor.Get("values").AsGodotDictionary(),actor.Get("display_name").AsString(),new HashSet<string>{"volume_db","pan","pitch"}));}foreach(var entry in owners){foreach(var pair in Dict(entry.Owner,"automation"))if(pair.Value.AsGodotArray().Count>0&&!entry.Allowed.Contains(pair.Key.AsString()))return entry.Label+": offline automation for "+pair.Key+" is not implemented. Remove or bake that automation before exporting.";foreach(string sourceKey in new[]{"instrument","generator"})foreach(var points in Dict(Dict(entry.Owner,sourceKey),"automation").Values)if(points.AsGodotArray().Count>0)return entry.Label+": automated instrument/generator parameters must be baked before offline export.";foreach(var raw in List(entry.Owner,"effects")){var effect=raw.AsGodotDictionary();if(!Bool(effect,"enabled",true))continue;var supported=GD.Load<GDScript>("res://Workspaces/AudioWorkspace/audio_effects.gd").Call("automation_commands",Text(effect,"type")).AsGodotDictionary();foreach(var parameter in Dict(effect,"automation"))if(parameter.Value.AsGodotArray().Count>0&&!supported.ContainsKey(parameter.Key.AsString()))return entry.Label+": "+parameter.Key+" automation is unsupported for "+Text(effect,"type")+"; bake or remove that automation.";}}return "";
    }
    public string pan_automation_filter(GArray points,double fallback){if(points.Count==0)return GD.Load<GDScript>("res://Workspaces/AudioWorkspace/audio_effects.gd").Call("pan_filter",fallback).AsString();string expression="clip(("+automation_expression(points,fallback)+"),-1,1)";return "aeval='val(0)*min(1,1-("+expression+"))|val(1)*min(1,1+("+expression+"))'";}
    public string gain_filter(GArray points,double fallback){string expression=automation_expression(points,fallback);return "aeval='val(0)*pow(10,("+expression+")/20)|val(1)*pow(10,("+expression+")/20)'";}
    public string automation_expression(GArray points,double fallback){if(points.Count==0)return Format(fallback);var ordered=new List<Settings>();foreach(var raw in points)ordered.Add(raw.AsGodotDictionary().Duplicate(true));ordered.Sort((first,last)=>Number(first,"time").CompareTo(Number(last,"time")));var array=new GArray();foreach(var point in ordered)array.Add(point);return automation_tree(array,0,array.Count-1);}
    public string automation_tree(GArray points,int first,int last){if(first==last){var a=points[first].AsGodotDictionary();if(first==points.Count-1)return Format(a["value"]);var b=points[first+1].AsGodotDictionary();string weight="clip((t-"+Format(a["time"])+")/"+Format(Math.Max(.000001,Number(b,"time")-Number(a,"time")))+",0,1)";if(Text(a,"curve")=="smooth")weight="("+weight+")*("+weight+")*(3-2*("+weight+"))";return Text(a,"curve")=="hold"?Format(a["value"]):Format(a["value"])+"+("+Format(Number(b,"value")-Number(a,"value"))+")*("+weight+")";}int middle=(first+last)/2;return "if(lt(t,"+Format(points[middle+1].AsGodotDictionary()["time"])+"),"+automation_tree(points,first,middle)+","+automation_tree(points,middle+1,last)+")";}
    public Settings publish_complete(string temporary,string destination,RefCounted? job)
    {
        string absolute=ProjectSettings.GlobalizePath(destination);if(Cancelled(job))return Failure("Cancelled.");if(Godot.FileAccess.FileExists(absolute))return Failure("The destination appeared during rendering. Choose a new name; it was not overwritten.");if(DirAccess.MakeDirRecursiveAbsolute(absolute.GetBaseDir())!=Error.Ok)return Failure("Could not create the export directory.");string staged=absolute+".kiwi-"+ActorData.new_id()+".partial";var copied=DirAccess.CopyAbsolute(temporary,staged);if(copied!=Error.Ok){DirAccess.RemoveAbsolute(staged);return Failure("Could not stage the completed render ("+(int)copied+").");}string error="";lock(PublishGate){if(Cancelled(job))error="Cancelled.";else if(Godot.FileAccess.FileExists(absolute))error="The destination appeared during rendering. Choose a new name; it was not overwritten.";else try{System.IO.File.Move(staged,absolute,false);}catch(Exception failure){error=System.IO.File.Exists(absolute)?"The destination appeared during rendering. Choose a new name; it was not overwritten.":"Could not publish the completed render ("+failure.Message+").";}}if(error.Length>0)DirAccess.RemoveAbsolute(staged);return new Settings {["success"]=error.Length==0,["error"]=error};
    }
    public Settings finish_process_files(Settings result,string directory){if(Bool(result,"cleanup_pending")){result["temporary_directory"]=directory;result["cleanup_warning"]="Encoder exit was not confirmed. Retained temporary files: "+directory;GD.PushWarning(result["cleanup_warning"].AsString());}else{var remaining=remove_owned(directory);if(remaining.Length>0){result["temporary_directory"]=directory;result["cleanup_warning"]="Some owned temporary files could not be removed: "+directory;GD.PushWarning(result["cleanup_warning"].AsString());}}return result;}
    public string[] remove_owned(string directory){var remaining=new List<string>();using var access=DirAccess.Open(directory);if(access==null)return remaining.ToArray();foreach(string file in access.GetFiles()){string path=directory.PathJoin(file);if(DirAccess.RemoveAbsolute(path)!=Error.Ok)remaining.Add(path);}if(DirAccess.RemoveAbsolute(directory)!=Error.Ok)remaining.Add(directory);return remaining.ToArray();}
    public string selection_error(RefCounted? document,Settings options)
    {
        if(document==null)return "The audio composition is unavailable.";if(options.TryGetValue("clip_ids",out var selection)){if(selection.VariantType!=Variant.Type.Array||selection.AsGodotArray().Count==0)return "Select at least one clip before exporting selected clips.";var available=new HashSet<string>();foreach(var raw in document.Get("clips").AsGodotArray()){var clip=raw.AsGodotObject();if(clip!=null)available.Add(clip.Get("id").AsString());}foreach(var id in selection.AsGodotArray())if(id.VariantType is not Variant.Type.String and not Variant.Type.StringName||id.AsString().Length==0||!available.Contains(id.AsString()))return "A selected clip is missing. Select the intended clips and export again.";}if(options.TryGetValue("track_id",out var trackId)&&(trackId.VariantType is not Variant.Type.String and not Variant.Type.StringName||trackId.AsString().Length==0||document.Call("track_for_id",trackId.AsString()).AsGodotDictionary().Count==0))return "Select an existing track before exporting or bouncing it.";return "";
    }
}
